local U = { nextTry = 0 }
function U.list()
    local out = {}
    if (D.passAll and M.attr(D.passAll) == true) or M.boost("UnlockAllDisasters") then return out end
    for _, d in ipairs(D.Cat and D.Cat.List or {}) do
        if not d.ComingSoon and d.Unlock and d.Unlock.Kind == "Coins" and M.attr("Unlocked_" .. d.Id) ~= true then out[#out + 1] = d end
    end
    table.sort(out, function(a, b) return a.Unlock.Price < b.Unlock.Price end)
    return out
end
function U.next() return U.list()[1] end
function U.keep() return tonumber(val("u_keep", "0")) or 0 end
function U.can()
    local n = U.next()
    return n and M.num("Coins") >= n.Unlock.Price + U.keep()
end
function U.tick()
    if not on("u_auto") or not M.ready() or os.clock() < U.nextTry then return end
    local n = U.next()
    if n and U.can() then
        M.fire("RequestUnlockDisaster", n.Id)
        U.nextTry = os.clock() + 1.1
        task.delay(1, function()
            if M.attr("Unlocked_" .. n.Id) == true then S.unlocked += 1 LOG("unlocked", n.Id) end
        end)
    end
end
local C = { dailyAt = 0, timeAt = {} }
function C.held()
    if not (on("r_wait") and on("u_auto") and U.can()) then
        C.heldAt = nil
        return false
    end
    C.heldAt = C.heldAt or os.clock()
    return os.clock() - C.heldAt < 20
end
function C.tick()
    if not M.ready() then return end
    local day, now = M.day(), os.clock()
    if on("r_daily") and M.num("DailyLastDay") < day and now - C.dailyAt > 6 and not C.held() then
        C.dailyAt = now
        M.fire("RequestClaimDaily")
        LOG("claim daily")
    end
    if not on("r_time") or C.held() or not D.Eco then return end
    local started = M.attr("TimeRewardStartedAt")
    if type(started) ~= "number" then return end
    local played = M.now() - started
    for _, r in ipairs(D.Eco.TimeRewards or {}) do
        local done = M.attr("TimeRewardDay") == day and M.attr("TimeRewardClaimed_" .. r.Minutes) == true
        if not done and played >= r.Minutes * 60 and now - (C.timeAt[r.Minutes] or -99) > 5 then
            C.timeAt[r.Minutes] = now
            M.fire("RequestClaimTimeReward", r.Minutes)
            S.claimed += 1
            LOG("claim time", r.Minutes)
            return
        end
    end
end
local R = { nextAt = 0, DESK = Vector3.new(12, 21, -74), lastState = nil }
function R.obj() return ReplicatedStorage:FindFirstChild("Reactor") end
function R.drive(r)
    local root = M.root()
    if not root then return end
    local home = root.Position
    S.task = __T["Starting meltdown"]
    M.go(R.DESK)
    task.wait(1.8)
    if r:GetAttribute("Scrammed") == true or r:GetAttribute("State") == "Shutdown" then
        M.fire("RequestReactorAction", "Reset", nil)
        task.wait(0.6)
    end
    for _ = 1, 10 do
        if r:GetAttribute("Override") == true then break end
        M.go(R.DESK)
        M.fire("RequestReactorAction", "Override", 1)
        task.wait(0.6)
    end
    for _ = 1, 16 do
        if (tonumber(r:GetAttribute("RodsWanted")) or 0) >= 10 then break end
        M.fire("RequestReactorAction", "Rods", 1)
        task.wait(0.35)
    end
    for _, k in ipairs({ "PumpA", "PumpB", "Eccs", "Vent" }) do
        if r:GetAttribute(k) == true then M.fire("RequestReactorAction", k, 0) task.wait(0.35) end
    end
    task.wait(0.3)
    M.go(home + Vector3.new(0, 3, 0))
end
function R.tick()
    if not on("m_melt") or S.travelTo or M.map() ~= "NuclearFacility" or not M.ready() then return end
    local r = R.obj()
    if not r then return end
    local st, now = r:GetAttribute("State"), os.clock()
    if st ~= R.lastState then
        LOG("reactor", tostring(st), "T", tostring(r:GetAttribute("Temperature")))
        if st == "Meltdown" then S.melts += 1 R.nextAt = now + 600 end
        if st == "Hot" or st == "Danger" or st == "Meltdown" then R.tries = 0 end
        R.lastState = st
    end
    if r:GetAttribute("Destroyed") == true or st == "Destroyed" or st == "Damaged" then
        if now > (R.fixAt or 0) then
            R.fixAt = now + 5
            M.restore()
        end
        return
    end
    if (st == "Stable" or st == "Shutdown") and r:GetAttribute("Source") ~= "None" and now >= R.nextAt then
        R.tries = (R.tries or 0) + 1
        R.nextAt = now + (R.tries >= 3 and 300 or 45)
        if R.tries >= 3 then R.tries = 0 end
        R.drive(r)
    end
end
