function UI.travel(id)
    if S.travelTo then notify(__T["Already travelling"]) return end
    S.travelTo = id
    notify(__T["Travelling when disasters end"])
    task.spawn(function()
        local ev = D.Rm and D.Rm:FindFirstChild("MapTravel")
        local stayed = false
        local con = ev and ev.OnClientEvent:Connect(function(a) if a == "Stayed" then stayed = true end end)
        for _ = 1, 4 do
            while RUNNING and os.clock() < (S.busyUntil or 0) do task.wait(0.25) end
            if not RUNNING then break end
            stayed = false
            M.fire("RequestChangeMap", id)
            local t0 = os.clock()
            while RUNNING and not stayed and os.clock() - t0 < 12 do task.wait(0.1) end
            if not stayed then break end
            task.wait(4)
        end
        if con then con:Disconnect() end
        if RUNNING then
            S.travelTo = nil
            notify(__T["Could not travel, try again"])
        end
    end)
end
