task.spawn(function()
    local hist = {}
    while RUNNING do
        pcall(function()
            local now, earned = os.clock(), M.num("Stat_TotalEarned")
            hist[#hist + 1] = { now, earned }
            while #hist > 2 and now - hist[1][1] > 60 do table.remove(hist, 1) end
            local dt = now - hist[1][1]
            local rate = dt > 3 and (earned - hist[1][2]) / dt * 60 or 0
            local intact, total = F.intact()
            setText(UI.s1, string.format(__T["Coins %s · %s/min"], M.coins(M.num("Coins")), M.coins(rate)))
            local chain = M.attr("ComboEndsAt") and M.now() < M.attr("ComboEndsAt") and math.max(M.num("ComboChain"), 1) or 1
            setText(UI.s2, string.format(__T["Combo %.2gx · Disasters %d"], math.min(1 + 0.25 * (chain - 1), 2.5), #F.list()))
            setText(UI.s3, string.format(__T["Buildings %d/%d · NPCs %d"], #intact, total, M.num("NpcCount")))
            setText(UI.s4, __T["Doing: "] .. S.task)
            setText(UI.s5, now - (S.gmsgAt or 0) < 8 and S.gmsg or string.format(__T["Fired %d · Restores %d"], S.fired, S.restores))
            local n = U.next()
            setText(UI.u1, n and string.format(__T["Next: %s · %s"], n.Name, M.coins(n.Unlock.Price)) or __T["All unlocked"])
            local day, list = M.day(), D.Eco and gcall(D.Eco.tasksFor, M.day()) or {}
            for i = 1, 3 do
                local t = list[i]
                if t then
                    local today = M.attr("TaskDay") == day
                    local cur = today and M.num("Stat_" .. t.Stat) - M.num("TaskStart_" .. t.Stat) or 0
                    local done = today and M.attr("TaskDone_" .. t.Id) == true
                    local name = gcall(D.Eco.taskName, t, tostring(t.Goal)) or t.Id
                    setText(UI["t" .. i], string.format("%s: %s", name, done and __T["Done"] or (math.min(math.max(cur, 0), t.Goal) .. "/" .. t.Goal)))
                end
            end
            local r = R.obj()
            if M.map() == "NuclearFacility" and r then
                setText(UI.m1, string.format("%s · %d°", tostring(r:GetAttribute("State")), tonumber(r:GetAttribute("Temperature")) or 0))
            else
                setText(UI.m1, __T["Travel here to use"])
            end
        end)
        task.wait(0.5)
    end
end)
